```zig
const std = @import("std");
const mem = std.mem;

pub const ChangeError = error{
    NegativeTarget,
    UnreachableTarget,
};

pub fn findFewestCoins(
    allocator: mem.Allocator,
    coins: []const u64,
    target: i64,
) (mem.Allocator.Error || ChangeError)![]u64 {
    if (target < 0) {
        return error.NegativeTarget;
    }
    if (target == 0) {
        return allocator.alloc(u64, 0);
    }

    const t: usize = @intCast(usize, target);
    const INF: usize = t + 1;

    var dp = try allocator.alloc(usize, t + 1);
    defer allocator.free(dp);
    var prev = try allocator.alloc(u64, t + 1);
    defer allocator.free(prev);

    for (0..t+1) |i| {
        dp[i] = INF;
    }
    dp[0] = 0;

    for (1..t+1) |amt| {
        for (coins) |c| {
            if (c > amt) continue;
            const c_usize = @intCast(usize, c);
            const prev_amt = amt - c_usize;
            const prev_count = dp[prev_amt];
            if (prev_count + 1 < dp[amt]) {
                dp[amt] = prev_count + 1;
                prev[amt] = c;
            }
        }
    }

    if (dp[t] == INF) {
        return error.UnreachableTarget;
    }

    var list = std.ArrayList(u64).init(allocator);
    defer list.deinit();

    var amt = t;
    while (amt > 0) {
        const coin = prev[amt];
        try list.append(coin);
        amt -= @intCast(usize, coin);
    }

    std.sort.sort(u64, list.items, {}, asc);

    return list.toOwnedSlice();
}

fn asc(a: u64, b: u64) bool {
    return a < b;
}
